import{_ as e,c as a,o as l,a0 as r}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"no/blog/elite-goal-setting.md","filePath":"no/blog/elite-goal-setting.md"}');const n=e({name:"no/blog/elite-goal-setting.md"},[["render",function(e,t,n,i,s,o){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="malsetting-for-eliteutøvere" tabindex="-1">Målsetting for eliteutøvere <a class="header-anchor" href="#malsetting-for-eliteutøvere" aria-label="Permalink to &quot;Målsetting for eliteutøvere&quot;">​</a></h1><p>Målsetting virker enkelt: bestem deg for hva du vil, og jobb mot det. Men målsetting på elitenivå er mer nyansert. De riktige målene akselererer utviklingen; de gale målene skaper frustrasjon og stagnasjon.</p><h2 id="utover-grunnleggende-mal" tabindex="-1">Utover grunnleggende mål <a class="header-anchor" href="#utover-grunnleggende-mal" aria-label="Permalink to &quot;Utover grunnleggende mål&quot;">​</a></h2><p>De fleste spillere setter seg mål for resultatet: «Vinne regionmesterskapet». Disse målene har problemer:</p><ul><li>Du kan ikke kontrollere resultatene fullt ut</li><li>De skaper press uten retning</li><li>Suksess eller fiasko er binært</li><li>De veileder ikke den daglige praksisen</li></ul><p>Elitemålsetting går dypere.</p><h2 id="malhierarkiet" tabindex="-1">Målhierarkiet <a class="header-anchor" href="#malhierarkiet" aria-label="Permalink to &quot;Målhierarkiet&quot;">​</a></h2><h3 id="niva-1-drømmemal-1–5-ar" tabindex="-1">Nivå 1: Drømmemål (1–5 år) <a class="header-anchor" href="#niva-1-drømmemal-1–5-ar" aria-label="Permalink to &quot;Nivå 1: Drømmemål (1–5 år)&quot;">​</a></h3><p>Dine ultimate ambisjoner:</p><ul><li>&quot;Konkurrer på nasjonalt nivå&quot;</li><li>&quot;Bli anerkjent som en eliteskytter&quot;</li><li>&quot;Vinne et stort mesterskap&quot;</li></ul><p>Disse gir retning og motivasjon, men er ikke handlingsrettede i det daglige.</p><h3 id="niva-2-prestasjonsmal-sesong-ar" tabindex="-1">Nivå 2: Prestasjonsmål (sesong/år) <a class="header-anchor" href="#niva-2-prestasjonsmal-sesong-ar" aria-label="Permalink to &quot;Nivå 2: Prestasjonsmål (sesong/år)&quot;">​</a></h3><p>Målbare forbedringer i spillet ditt:</p><ul><li>&quot;Øk skytepresisjonen fra 60 % til 70 %&quot;</li><li>&quot;Reduser upålagte feil med 25 %&quot;</li><li>&quot;Utvikle en pålitelig plombée&quot;</li></ul><p>Disse er innenfor din kontroll og målbare.</p><h3 id="niva-3-prosessmal-daglig-ukentlig" tabindex="-1">Nivå 3: Prosessmål (daglig/ukentlig) <a class="header-anchor" href="#niva-3-prosessmal-daglig-ukentlig" aria-label="Permalink to &quot;Nivå 3: Prosessmål (daglig/ukentlig)&quot;">​</a></h3><p>Tiltakene som driver forbedring:</p><ul><li>&quot;Komplett rutine før skuddet på hvert kast&quot;</li><li>&quot;Øv visualisering i 10 minutter daglig&quot;</li><li>&quot;Tren skyteteknikk 3 ganger i uken&quot;</li></ul><p>Disse er fullt kontrollerbare og bygger mot ytelsesmål.</p><h2 id="smart-rammeverket" tabindex="-1">SMART+-rammeverket <a class="header-anchor" href="#smart-rammeverket" aria-label="Permalink to &quot;SMART+-rammeverket&quot;">​</a></h2><p>Gå utover grunnleggende SMART-mål:</p><h3 id="spesiell" tabindex="-1">Spesiell <a class="header-anchor" href="#spesiell" aria-label="Permalink to &quot;Spesiell&quot;">​</a></h3><p>Ikke «forbedre pekingen min», men «utvikle en konsistent demiportée som lander innenfor 30 cm fra målet fra 8 meter».</p><h3 id="malbar" tabindex="-1">Målbar <a class="header-anchor" href="#malbar" aria-label="Permalink to &quot;Målbar&quot;">​</a></h3><p>Definer hvordan du skal spore fremdriften:</p><ul><li>Suksessrateprosenter</li><li>Konsistensmålinger</li><li>Markører for videoanalyse</li></ul><h3 id="oppnaelig-men-utfordrende" tabindex="-1">Oppnåelig, men utfordrende <a class="header-anchor" href="#oppnaelig-men-utfordrende" aria-label="Permalink to &quot;Oppnåelig, men utfordrende&quot;">​</a></h3><p>Målet bør kreve vekst, men være realistisk. En skytter på 60 % som sikter mot 65 % er oppnåelig; en sikting mot 90 % er fantasi.</p><h3 id="relevant" tabindex="-1">Relevant <a class="header-anchor" href="#relevant" aria-label="Permalink to &quot;Relevant&quot;">​</a></h3><p>Mål må knyttes til dine større ambisjoner og adressere faktiske svakheter, ikke bare det som er lett å forbedre.</p><h3 id="tidsbundet" tabindex="-1">Tidsbundet <a class="header-anchor" href="#tidsbundet" aria-label="Permalink to &quot;Tidsbundet&quot;">​</a></h3><p>Sett tydelige tidsfrister:</p><ul><li>&quot;Innen sesongslutt&quot;</li><li>&quot;Innen 3 måneder&quot;</li><li>&quot;Ved det nasjonale mesterskapet&quot;</li></ul><h3 id="personlig-meningsfull" tabindex="-1">+ Personlig meningsfull <a class="header-anchor" href="#personlig-meningsfull" aria-label="Permalink to &quot;+ Personlig meningsfull&quot;">​</a></h3><p>Målet må bety noe for DEG, ikke bare treneren eller lagkameratene dine. Indre motivasjon opprettholder innsatsen når fremgangen er langsom.</p><h2 id="prosess-vs-resultatfokus" tabindex="-1">Prosess vs. resultatfokus <a class="header-anchor" href="#prosess-vs-resultatfokus" aria-label="Permalink to &quot;Prosess vs. resultatfokus&quot;">​</a></h2><h3 id="problemet-med-resultatmal" tabindex="-1">Problemet med resultatmål <a class="header-anchor" href="#problemet-med-resultatmal" aria-label="Permalink to &quot;Problemet med resultatmål&quot;">​</a></h3><p>«Å vinne kampen» skaper problemer:</p><ul><li>Angst for ting du ikke kan kontrollere</li><li>Distraksjon fra utførelsen</li><li>Alt-eller-ingenting-tenkning</li><li>Press uten veiledning</li></ul><h3 id="kraften-i-prosessmal" tabindex="-1">Kraften i prosessmål <a class="header-anchor" href="#kraften-i-prosessmal" aria-label="Permalink to &quot;Kraften i prosessmål&quot;">​</a></h3><p>«Utfør rutinen min før bruk perfekt» tilbyr:</p><ul><li>Full kontroll</li><li>Klart fokus</li><li>Umiddelbar tilbakemelding</li><li>Bygger naturlig mot resultater</li></ul><h3 id="balansen" tabindex="-1">Balansen <a class="header-anchor" href="#balansen" aria-label="Permalink to &quot;Balansen&quot;">​</a></h3><p>Bruk resultatmål for motivasjon og retning. Bruk prosessmål for daglig fokus og gjennomføring.</p><h2 id="malsetting-for-ulike-faser" tabindex="-1">Målsetting for ulike faser <a class="header-anchor" href="#malsetting-for-ulike-faser" aria-label="Permalink to &quot;Målsetting for ulike faser&quot;">​</a></h2><h3 id="lavsesong" tabindex="-1">Lavsesong <a class="header-anchor" href="#lavsesong" aria-label="Permalink to &quot;Lavsesong&quot;">​</a></h3><p>Fokus på utviklingsmål:</p><ul><li>Tekniske forbedringer</li><li>Fysisk kondisjonering</li><li>Mental ferdighetsbygging</li><li>Utvider palett av pledd</li></ul><h3 id="før-sesong" tabindex="-1">Før-sesong <a class="header-anchor" href="#før-sesong" aria-label="Permalink to &quot;Før-sesong&quot;">​</a></h3><p>Overgang til integrering:</p><ul><li>Kombinere ferdigheter i kamplignende forhold</li><li>Testing av forbedringer i vennskapelig konkurranse</li><li>Raffinering av strategier</li></ul><h3 id="konkurransesesong" tabindex="-1">Konkurransesesong <a class="header-anchor" href="#konkurransesesong" aria-label="Permalink to &quot;Konkurransesesong&quot;">​</a></h3><p>Skift til ytelse og prosess:</p><ul><li>Å gjennomføre det du har utviklet</li><li>Prosess mål for hver kamp</li><li>Minimale tekniske endringer</li></ul><h3 id="etter-konkurransen" tabindex="-1">Etter konkurransen <a class="header-anchor" href="#etter-konkurransen" aria-label="Permalink to &quot;Etter konkurransen&quot;">​</a></h3><p>Refleksjon og planlegging:</p><ul><li>Analyser hva som fungerte</li><li>Identifiser områder for vekst</li><li>Sett mål for neste syklus</li></ul><h2 id="vanlige-feil-ved-malsetting" tabindex="-1">Vanlige feil ved målsetting <a class="header-anchor" href="#vanlige-feil-ved-malsetting" aria-label="Permalink to &quot;Vanlige feil ved målsetting&quot;">​</a></h2><h3 id="for-mange-mal" tabindex="-1">For mange mål <a class="header-anchor" href="#for-mange-mal" aria-label="Permalink to &quot;For mange mål&quot;">​</a></h3><p>Fokus er makt. 2–3 viktige mål slår 10 spredte mål.</p><h3 id="kun-resultatmal" tabindex="-1">Kun resultatmål <a class="header-anchor" href="#kun-resultatmal" aria-label="Permalink to &quot;Kun resultatmål&quot;">​</a></h3><p>Uten prosessmål har du ingen plan.</p><h3 id="ingen-fleksibilitet" tabindex="-1">Ingen fleksibilitet <a class="header-anchor" href="#ingen-fleksibilitet" aria-label="Permalink to &quot;Ingen fleksibilitet&quot;">​</a></h3><p>Mål bør tilpasses ny informasjon. Streng overholdelse av utdaterte mål er sløsing med innsats.</p><h3 id="sammenligningsbaserte-mal" tabindex="-1">Sammenligningsbaserte mål <a class="header-anchor" href="#sammenligningsbaserte-mal" aria-label="Permalink to &quot;Sammenligningsbaserte mål&quot;">​</a></h3><p>«Vær bedre enn [spiller]» legger suksessen din i andres hender.</p><h3 id="forsømmelse-av-mentale-mal" tabindex="-1">Forsømmelse av mentale mål <a class="header-anchor" href="#forsømmelse-av-mentale-mal" aria-label="Permalink to &quot;Forsømmelse av mentale mål&quot;">​</a></h3><p>Tekniske og fysiske mål dominerer, men mentale ferdigheter avgjør ofte hvem som vinner.</p><h2 id="implementeringsstrategier" tabindex="-1">Implementeringsstrategier <a class="header-anchor" href="#implementeringsstrategier" aria-label="Permalink to &quot;Implementeringsstrategier&quot;">​</a></h2><h3 id="skriv-dem-ned" tabindex="-1">Skriv dem ned <a class="header-anchor" href="#skriv-dem-ned" aria-label="Permalink to &quot;Skriv dem ned&quot;">​</a></h3><p>Det er betydelig større sannsynlighet for at skriftlige mål blir nådd.</p><h3 id="gjennomga-regelmessig" tabindex="-1">Gjennomgå regelmessig <a class="header-anchor" href="#gjennomga-regelmessig" aria-label="Permalink to &quot;Gjennomgå regelmessig&quot;">​</a></h3><p>Ukentlig gjennomgang holder målene presentert og gir mulighet for justeringer.</p><h3 id="del-selektivt" tabindex="-1">Del selektivt <a class="header-anchor" href="#del-selektivt" aria-label="Permalink to &quot;Del selektivt&quot;">​</a></h3><p>Del med de som vil støtte, ikke undergrave.</p><h3 id="visualiser-prestasjon" tabindex="-1">Visualiser prestasjon <a class="header-anchor" href="#visualiser-prestasjon" aria-label="Permalink to &quot;Visualiser prestasjon&quot;">​</a></h3><p>Se regelmessig for deg at du når målene dine – følelsen, øyeblikket.</p><h3 id="spor-fremgang" tabindex="-1">Spor fremgang <a class="header-anchor" href="#spor-fremgang" aria-label="Permalink to &quot;Spor fremgang&quot;">​</a></h3><p>Det som blir målt, blir håndtert. Hold oversikt.</p><h2 id="nar-malene-ikke-blir-nadd" tabindex="-1">Når målene ikke blir nådd <a class="header-anchor" href="#nar-malene-ikke-blir-nadd" aria-label="Permalink to &quot;Når målene ikke blir nådd&quot;">​</a></h2><p>Uoppnådde mål er ikke feil – de er data:</p><ol><li><strong>Analyser</strong>: Hvorfor ble det ikke oppnådd?</li><li><strong>Lær</strong>: Hva lærer dette deg?</li><li><strong>Juster</strong>: Endre målet eller tilnærmingen</li><li><strong>Fortsett</strong>: Utholdenhet slår perfeksjon</li></ol><h2 id="det-mentale-spillet-om-mal" tabindex="-1">Det mentale spillet om mål <a class="header-anchor" href="#det-mentale-spillet-om-mal" aria-label="Permalink to &quot;Det mentale spillet om mål&quot;">​</a></h2><p>Mål påvirker psykologien:</p><ul><li><strong>For lett</strong>: Kjedsomhet, selvtilfredshet</li><li><strong>For vanskelig</strong>: Angst, motløshet</li><li><strong>Akkurat passe</strong>: Engasjement, flyt, vekst</li></ul><p>Finn det optimale punktet der målene utfordrer uten å bli overveldende.</p><hr><p>| <em>Relatert: <a href="/no/utdanning/mål/">Introduksjon til målsetting</a> | <a href="/no/utdanning/mål/smarte-mål">SMART-mål</a> | <a href="/no/utdanning/mål/planlegging">Planlegging av utviklingen din</a></em> |</p>',88)])])}]]);export{t as __pageData,n as default};
